// Wuthering Tools+ — the banner data the app ships, for every caller that used to read the seed alone:
//   bannerSeed.json    GENERATED by tools/emitBannerSeed.ts from the Convene notices in Kuro's news feed. Never hand-edited.
//   bannerManual.json  HAND-ENTERED: banners Kuro announced in an image post only. The feed has had no Convene notice
//                      for a new resonator's own banner since version 3.6 (Jingran, Hsin, Suoming, Lily), so the
//                      generator cannot see them. One record per image post, keyed by that post's article id (the
//                      card's "Kuro's notice" link opens it), with what the image states: the banner title, the 5-star,
//                      the 4-stars, the Duration line. Released content only: a banner goes in once it has started.
// The same rule as /today's hand-entered events (today/data/rules.json `manualEvents`): Kuro's text wins. A text
// notice of the same banner (same kind, 5-star and dates) folds into one card in `buildBannerList`, and a generated
// record with the same article id replaces the hand-entered one.
import { mergeBannerCaches, type BannerCache } from "../banners";
import manualFile from "./bannerManual.json";
import seedFile from "./bannerSeed.json";

const unwrap = (m: unknown): BannerCache => ((m as { default?: unknown }).default ?? m) as BannerCache;

/** the hand-entered records alone */
export const MANUAL_BANNERS: BannerCache = unwrap(manualFile);
/** the generated seed ∪ the hand-entered records: what `loadBanners({ seed })` is given */
export const SHIPPED_BANNERS: BannerCache = mergeBannerCaches(MANUAL_BANNERS, unwrap(seedFile));
